  5		import { onMount } from 'svelte';
  6		import {
  7			Sidebar,
  8			SidebarContent,
  9			SidebarFooter,
 10			SidebarGroup,
 11			SidebarGroupContent,
 12			SidebarGroupLabel,
 13			SidebarHeader,
 14			SidebarMenu,
 15			SidebarMenuBadge,
 16			SidebarMenuButton,
 17			SidebarMenuItem,
 18			SidebarRail,
 19			SidebarSeparator
 20		} from '$lib/components/ui/sidebar';
 21		import { Badge } from '$lib/components/ui/badge';
 22		import { fetchSessionContext, fetchObservations, fetchInbox, fetchTasks } from '$lib/api';
 23		import type { SessionContext } from '@kynetic-ai/shared';
 24		import ConnectionStatus from '$lib/components/ConnectionStatus.svelte';
 25		import ProjectSelector from '$lib/components/ProjectSelector.svelte';
 26		import {
 27			hasMultipleProjects,
 28			getProjectVersion,
 29			isInitialized as isProjectInitialized
 30		} from '$lib/stores/project.svelte';
 31		import { isStaticMode } from '$lib/stores/mode.svelte';
 32		import {
 33			LayoutDashboard,
 34			ListTodo,
 35			Bot,
 36			Terminal,
 37			FileText,
 38			Map,
 39			ShieldCheck,
 40			Inbox,
 41			Eye,
 42			Filter,
 43			Workflow,
 44			Settings,
 45			ChevronDown
 46		} from 'lucide-svelte';
 47	
 48		// AC: @ui-app-shell ac-1 — Grouped navigation sections
 49		type NavItem = {
 50			path: string;
 51			label: string;
 52			icon: typeof LayoutDashboard;
 53			badgeKey?: 'inbox' | 'observations' | 'pendingReview';
 54		};
 55	
 56		type NavGroup = {
 57			label: string;
 58			items: NavItem[];
 59		};
 60	
 61		const navGroups: NavGroup[] = [
 62			{
 63				label: 'Work',
 64				items: [
 65					{ path: '/', label: 'Dashboard', icon: LayoutDashboard },
 66					{ path: '/tasks', label: 'Tasks', icon: ListTodo, badgeKey: 'pendingReview' },
 67					{ path: '/agents', label: 'Agents', icon: Bot },
 68					{ path: '/sessions', label: 'Sessions', icon: Terminal }
 69				]
 70			},
 71			{
 72				label: 'Specs',
 73				items: [
 74					{ path: '/specs', label: 'Specs', icon: FileText },
 75					{ path: '/plans', label: 'Plans', icon: Map },
 76					{ path: '/validate', label: 'Validate', icon: ShieldCheck }
 77				]
 78			},
 79			{
 80				label: 'Capture',
 81				items: [
 82					{ path: '/inbox', label: 'Inbox', icon: Inbox, badgeKey: 'inbox' },
 83					// AC: @ui-app-shell ac-4 — Observations always visible (not hidden when count is 0)
 84					{ path: '/observations', label: 'Observations', icon: Eye, badgeKey: 'observations' },
 85					{ path: '/triage', label: 'Triage', icon: Filter }
 86				]
 87			},
 88			{
 89				label: 'Config',
 90				items: [
 91					{ path: '/workflows', label: 'Workflows', icon: Workflow },
 92					{ path: '/settings', label: 'Settings', icon: Settings }
 93				]
 94			}
 95		];
 96	
 97		// AC: @ui-app-shell ac-2 — Badge counts for actionable items
 98		let sessionContext = $state<SessionContext | null>(null);
 99		let inboxCount = $state(0);
100		let unresolvedObservationsCount = $state(0);
101		let pendingReviewCount = $state(0);
102	
103		let showProjectSelector = $derived(hasMultipleProjects());
104	
105		// Collapsed group state (all expanded by default)
106		let collapsedGroups = $state<Record<string, boolean>>({});
107	
108		function toggleGroup(label: string) {
109			collapsedGroups = { ...collapsedGroups, [label]: !collapsedGroups[label] };
110		}
111	
112		function isActive(itemPath: string): boolean {
113			const currentPath = $page.url.pathname;
114			const fullPath = `${base}${itemPath}`;
115			if (itemPath === '/') {
116				return currentPath === fullPath || currentPath === '/';
117			}
118			return currentPath === fullPath || currentPath.startsWith(`${fullPath}/`);
119		}
120	
121		function getBadgeCount(key?: 'inbox' | 'observations' | 'pendingReview'): number {
122			if (!key) return 0;
123			switch (key) {
124				case 'inbox':
125					return inboxCount;
126				case 'observations':
127					return unresolvedObservationsCount;
128				case 'pendingReview':
129					return pendingReviewCount;
130				default:
131					return 0;
132			}
133		}
134	
135		// Polling interval handle — set up once project store is ready
136		let countsInterval: ReturnType<typeof setInterval> | undefined;
137	
138		onMount(() => {
139			return () => {
140				if (countsInterval) clearInterval(countsInterval);
141			};
142		});
143	
144		// Load counts when project store is initialized and on every project change.
145		// This replaces the old onMount loadCounts() call which could fire before
146		// loadProjects() completed, causing stale/wrong-project badge counts.
147		$effect(() => {
148			const version = getProjectVersion();
149			const ready = isProjectInitialized();
150			if (!ready) return;
151	
152			// Initial load (version === 0) and subsequent project switches (version > 0)
153			loadCounts();
154	
155			// Set up polling interval on first ready signal
156			if (!countsInterval) {
157				countsInterval = setInterval(loadCounts, 30000);
158			}
159		});
160	
161		async function loadCounts() {
162			try {
163				const [sessionData, obsResponse, inboxResponse, tasksResponse] = await Promise.all([
164					fetchSessionContext(),
165					fetchObservations({ resolved: false }),
166					fetchInbox({ limit: 0 }),
167					fetchTasks({ status: 'pending_review', limit: 0 })
168				]);
169	
170				sessionContext = sessionData;
171				unresolvedObservationsCount = obsResponse.total;
172				inboxCount = inboxResponse.total;
173				pendingReviewCount = tasksResponse.total;
174			} catch (err) {
175				console.error('Failed to load sidebar counts:', err);
176			}
177		}
178	</script>
179	
180	<!-- AC: @ui-app-shell ac-1 — Collapsible sidebar with grouped navigation -->
181	<Sidebar>
182		<SidebarHeader>
183			<div class="flex items-center gap-2 px-4 py-2">
184				<span class="text-lg font-bold">kspec</span>
185			</div>
186		</SidebarHeader>
187	
188		<SidebarContent>
189			{#if showProjectSelector}
190				<SidebarGroup>
191					<SidebarGroupLabel>Project</SidebarGroupLabel>
192					<SidebarGroupContent>
193						<div class="px-2">
194							<ProjectSelector />
195						</div>
196					</SidebarGroupContent>
197				</SidebarGroup>
198			{/if}
199	
200			{#if sessionContext?.focus}
201				<SidebarGroup>
202					<SidebarGroupLabel>Current Focus</SidebarGroupLabel>
203					<SidebarGroupContent>
204						<div
205							class="px-4 py-2 text-sm italic text-muted-foreground"
206							data-testid="session-focus"
207						>
208							{sessionContext.focus}
209						</div>
210					</SidebarGroupContent>
211				</SidebarGroup>
212			{/if}
213	
214			{#each navGroups as group}
215				<SidebarGroup>
216					<SidebarGroupLabel>
217						<button
218							class="flex w-full items-center justify-between text-xs font-medium uppercase tracking-wider"
219							onclick={() => toggleGroup(group.label)}
220							data-testid="nav-group-{group.label.toLowerCase()}"
221						>
222							{group.label}
223							<ChevronDown
224								class="h-3 w-3 transition-transform {collapsedGroups[group.label]
225									? '-rotate-90'
226									: ''}"
227							/>
228						</button>
229					</SidebarGroupLabel>
230					{#if !collapsedGroups[group.label]}
231						<SidebarGroupContent>
232							<SidebarMenu data-testid="sidebar-nav-{group.label.toLowerCase()}">
233								{#each group.items as item}
234									<SidebarMenuItem>
235										<SidebarMenuButton
236											isActive={isActive(item.path)}
237											data-testid="nav-link-{item.label.toLowerCase()}"
238										>
239											{#snippet child({ props })}
240												<a href="{base}{item.path}" {...props}>
241													<item.icon class="h-4 w-4" />
242													<span>{item.label}</span>
243												</a>
244											{/snippet}
245										</SidebarMenuButton>
246										<!-- AC: @ui-app-shell ac-2 — Badge counts for actionable items -->
247										{#if item.badgeKey && getBadgeCount(item.badgeKey) > 0}
248											<SidebarMenuBadge data-testid="badge-{item.badgeKey}">
249												{getBadgeCount(item.badgeKey)}
250											</SidebarMenuBadge>
251										{/if}
252									</SidebarMenuItem>
253								{/each}
254							</SidebarMenu>
255						</SidebarGroupContent>
256					{/if}
257				</SidebarGroup>
258			{/each}
259		</SidebarContent>
