  1	/**
  2	 * Project Store
  3	 *
  4	 * Global project state managed via Svelte runes.
  5	 * Tracks registered projects, current selection, and provides reactive reload triggers.
  6	 *
  7	 * AC Coverage:
  8	 * - ac-25 (@multi-directory-daemon): Project selector shown when multiple projects registered
  9	 * - ac-26 (@multi-directory-daemon): Selection sets X-Kspec-Dir header for API requests
 10	 * - ac-27 (@multi-directory-daemon): UI reloads data on project change
 11	 * - ac-35 (@multi-directory-daemon): Projects listed in registration order
 12	 * - ac-36 (@multi-directory-daemon): Invalid project recovery
 13	 */
 14	
 15	import { browser } from '$app/environment';
 16	import { DAEMON_API_BASE } from '$lib/constants';
 17	
 18	const STORAGE_KEY = 'kspec-selected-project';
 19	
 20	export interface Project {
 21		path: string;
 22		registered_at: string;
 23		watcher_active: boolean;
 24	}
 25	
 26	// Reactive state using Svelte 5 runes
 27	let projects = $state<Project[]>([]);
 28	let selectedPath = $state<string | null>(null);
 29	let projectVersion = $state(0); // Increments on change to trigger reloads
 30	let loading = $state(false);
 31	let error = $state<string | null>(null);
 32	let initialized = $state(false);
 33	
 34	/**
 35	 * Load selected project from localStorage
 36	 */
 37	function loadPersistedSelection(): string | null {
 38		if (!browser) return null;
 39		try {
 40			return localStorage.getItem(STORAGE_KEY);
 41		} catch {
 42			return null;
 43		}
 44	}
 45	
 46	/**
 47	 * Persist selected project to localStorage
 48	 */
 49	function persistSelection(path: string | null): void {
 50		if (!browser) return;
 51		try {
 52			if (path) {
 53				localStorage.setItem(STORAGE_KEY, path);
 54			} else {
 55				localStorage.removeItem(STORAGE_KEY);
 56			}
 57		} catch {
 58			// localStorage may be unavailable (e.g., private browsing)
 59		}
 60	}
 61	
 62	/**
 63	 * Load projects list from daemon API
 64	 * AC: @multi-directory-daemon ac-35 - Returns projects in registration order
 65	 */
 66	export async function loadProjects(): Promise<void> {
 67		if (!browser) return;
 68	
 69		loading = true;
 70		error = null;
 71	
 72		try {
 73			const response = await fetch(`${DAEMON_API_BASE}/api/projects`);
 74			if (!response.ok) {
 75				throw new Error('Failed to load projects');
 76			}
 77	
 78			const data = await response.json();
 79			projects = data.projects || [];
 80	
 81			// Restore selection from localStorage or use first project as default
 82			const persisted = loadPersistedSelection();
 83			if (persisted && projects.some((p) => p.path === persisted)) {
 84				selectedPath = persisted;
 85			} else if (projects.length > 0) {
 86				// Default to first registered project
 87				selectedPath = projects[0].path;
 88				persistSelection(selectedPath);
 89			}
 90	
 91			initialized = true;
 92		} catch (err) {
 93			error = err instanceof Error ? err.message : 'Failed to load projects';
 94			console.error('[ProjectStore] Failed to load projects:', err);
 95		} finally {
 96			loading = false;
 97		}
 98	}
 99	
100	/**
101	 * Select a project
102	 * AC: @multi-directory-daemon ac-26, ac-27 - Sets header and triggers reload
103	 */
104	export function selectProject(path: string): void {
105		if (path === selectedPath) return;
106	
107		const projectExists = projects.some((p) => p.path === path);
108		if (!projectExists) {
109			console.warn('[ProjectStore] Attempted to select unknown project:', path);
110			return;
111		}
112	
113		selectedPath = path;
114		persistSelection(path);
115	
116		// Increment version to trigger data reloads in components
117		// AC: @multi-directory-daemon ac-27
118		projectVersion++;
119	}
120	
121	/**
122	 * Get the currently selected project path
123	 * AC: @multi-directory-daemon ac-26 - Used for X-Kspec-Dir header
124	 */
125	export function getSelectedProjectPath(): string | null {
126		return selectedPath;
127	}
128	
129	/**
130	 * Check if multiple projects are registered
131	 * AC: @multi-directory-daemon ac-25 - For conditional selector rendering
132	 */
133	export function hasMultipleProjects(): boolean {
134		return projects.length > 1;
135	}
136	
137	/**
138	 * Get the project version counter (for reactive dependencies)
139	 * AC: @multi-directory-daemon ac-27 - Components watch this to reload data
140	 */
141	export function getProjectVersion(): number {
142		return projectVersion;
143	}
144	
145	/**
146	 * Get all registered projects
147	 * AC: @multi-directory-daemon ac-25 - For project list display
148	 */
149	export function getProjects(): Project[] {
150		return projects;
151	}
152	
153	/**
154	 * Check if project store is loading
155	 */
156	export function isLoading(): boolean {
157		return loading;
158	}
159	
160	/**
161	 * Get error state
162	 */
163	export function getError(): string | null {
164		return error;
165	}
166	
167	/**
168	 * Check if project store has been initialized
169	 */
170	export function isInitialized(): boolean {
171		return initialized;
172	}
173	
174	/**
175	 * Clear invalid selection and prompt user to select valid project
176	 * AC: @multi-directory-daemon ac-36 - Invalid project recovery
177	 */
178	export function clearInvalidSelection(): void {
179		selectedPath = null;
180		persistSelection(null);
181		error = 'Selected project is no longer valid. Please select a project.';
182	}
183	
184	/**
185	 * Check if a path matches an API error indicating invalid project
186	 * Used by api.ts to detect when selected project becomes invalid
187	 */
188	export function isInvalidProjectError(response: Response, message?: string): boolean {
189		if (response.status !== 400 && response.status !== 404) return false;
190		if (!message) return false;
191		return (
192			message.includes('Invalid kspec project') ||
193			message.includes('No default project configured') ||
194			message.includes('Default project no longer valid')
195		);
196	}

